def juntar_fichas(apps, schema_editor):
    """Una ficha por RUT con los roles que ya tenía: la contraparte de ventas la marca como
    cliente; la de compras u honorarios, como proveedor."""
    Contraparte = apps.get_model('finanzas', 'Contraparte')
    Contacto = apps.get_model('finanzas', 'Contacto')
    for cp in Contraparte.objects.order_by('id'):
        contacto, _ = Contacto.objects.get_or_create(
            organization_id=cp.organization_id, rut=cp.rut,
            defaults={'razon_social': cp.razon_social or cp.rut})
        if cp.libro == 'ventas':
            contacto.es_cliente = True
        else:
            contacto.es_proveedor = True
        if not contacto.razon_social and cp.razon_social:
            contacto.razon_social = cp.razon_social
        contacto.save()
        cp.contacto = contacto
        cp.save(update_fields=['contacto'])


